"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisLogoCloudContent } from "./components/logo-cloud/content";
import View2 from "./components/logo-cloud/variants/03-columns";
const variants = {"columns":View2};
export type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "./components/logo-cloud/content";
export interface ArtemisLogoCloudProps { className?: string; variant?: "columns"; /** The words on the logo cloud; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisLogoCloudContent>; }
export function ArtemisLogoCloud({ className, variant = "columns", content }: ArtemisLogoCloudProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** One logo in the cloud. */
export interface ArtemisLogoCloudLogo {
  /**
   * The company's name, shown beside the icon. All layouts; carousel also lists every name for screen readers.
   * Keep names unique, since grid, columns and carousel tell logos apart by name.
   */
  name: string;
  /** A logo image shown in place of the icon and name, sized to the row; its alt text names the logo. All layouts. */
  image?: { src: string; alt: string };
  /** The icon beside the name. All layouts, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis logo cloud. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisLogoCloudContent {
  /** A small label over the headline. columns and carousel. */
  badge?: string;
  /** The heading. All layouts; marquee shows it as a small line over the logos. */
  headline: string;
  /** A line under or beside the headline. grid, columns and carousel. */
  subhead?: string;
  /**
   * The logos. All layouts: marquee scrolls them in one row, grid rolls them through eight cells, columns deals them
   * into four scrolling lanes and carousel turns them through two or four slots. Twelve look best; grid needs more
   * than eight to roll.
   */
  logos: ArtemisLogoCloudLogo[];
}

"use client";
// @zeus-internal
import { Aperture, Atom, Box, Circle, Command, Diamond, Gem, Hexagon, Octagon, Orbit, Triangle, } from "lucide-react";
import type { ComponentType, CSSProperties } from "react";
import type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "../content";
import { LayersIcon } from "./03-columns/icons";
/** The logos the columns show when given none. The lanes take them in turn: the first lane gets the first, fifth and ninth. */
const defaultLogos: ArtemisLogoCloudLogo[] = [
    { name: "Workspace" },
    { name: "Group A" },
    { name: "Group B" },
    { name: "Group C" },
    { name: "Group D" },
    { name: "Group E" },
    { name: "Group F" },
    { name: "Group G" },
    { name: "Group H" },
    { name: "Group I" },
    { name: "Group J" },
    { name: "Group K" },
];
const DEFAULT = {
    badge: "In good company",
    headline: "A living field of teams building what comes next.",
    subhead: "Independent studios, growing products, and global platforms use the same foundation without ending up with the same design.",
    logos: defaultLogos,
} satisfies ArtemisLogoCloudContent;
/** The icon for each slot, for logos that come without one. */
const ICONS = [Hexagon, Triangle, Aperture, Box, Gem, Command, Octagon, Circle, Diamond, LayersIcon, Atom, Orbit];
type Lane = {
    duration: number;
    reverse: boolean;
};
/** A logo and its place in the list, which picks its default icon. */
type Placed = {
    logo: ArtemisLogoCloudLogo;
    slot: number;
};
const LANES: Lane[] = [
    {
        duration: 22,
        reverse: false,
    },
    {
        duration: 25,
        reverse: true,
    },
    {
        duration: 28,
        reverse: false,
    },
    {
        duration: 31,
        reverse: true,
    },
];
const KEYFRAMES = `
  @keyframes artemis-c1ec26e-artemis-logo-column-scroll {
    from { transform: translate3d(0, 0, 0); }
    to { transform: translate3d(0, -50%, 0); }
  }

  .art\\:artemis-logo-column:hover .art\\:artemis-logo-column-track {
    animation-play-state: paused;
  }
`;
function LogoCell({ logo, slot }: Placed) {
    const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = logo.icon ?? ICONS[slot % ICONS.length];
    return (<div className="art:flex art:h-[6.5rem] art:items-center art:border-border/70 art:border-b art:px-3 art:@min-[640px]/artemis:px-5">
      <span className="art:inline-flex art:min-w-0 art:items-center art:gap-2.5 art:text-muted-foreground art:transition-[color,transform] art:duration-300 art:group-hover:text-foreground art:hover:translate-x-1">
        {logo.image ? <img src={logo.image.src} alt={logo.image.alt} className="art:h-5 art:w-auto art:max-w-full art:object-contain art:@min-[640px]/artemis:h-6"/> : <>
        <Icon className="art:shrink-0 art:size-4 art:@min-[640px]/artemis:size-5" strokeWidth={1.75} aria-hidden="true"/>
        <span className="art:truncate art:font-semibold art:tracking-tight art:text-sm art:@min-[640px]/artemis:text-base">{logo.name}</span>
        </>}
      </span>
    </div>);
}
function LogoLane({ lane, logos }: {
    lane: Lane;
    logos: Placed[];
}) {
    const trackStyle: CSSProperties = {
        animationName: "artemis-c1ec26e-artemis-logo-column-scroll",
        animationDuration: `${lane.duration}s`,
        animationTimingFunction: "linear",
        animationIterationCount: "infinite",
        animationDirection: lane.reverse ? "reverse" : "normal",
    };
    return (<div className="art:artemis-logo-column art:group art:overflow-hidden art:border-border art:border-l art:odd:border-l-0 art:hover:bg-muted/20 art:@min-[640px]/artemis:odd:border-l art:@min-[640px]/artemis:first:border-l-0">
      <div className="art:artemis-logo-column-track art:will-change-transform" style={trackStyle}>
        <div>
          {logos.map(({ logo, slot }) => (<LogoCell key={logo.name} logo={logo} slot={slot}/>))}
        </div>
        <div aria-hidden="true">
          {logos.map(({ logo, slot }) => (<LogoCell key={logo.name} logo={logo} slot={slot}/>))}
        </div>
      </div>
    </div>);
}
export default function LogoCloudColumns({ content }: { content?: Partial<ArtemisLogoCloudContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const placed = copy.logos.map((logo, slot) => ({ logo, slot }));
    const lanes = LANES.map((lane, index) => ({ lane, logos: placed.filter(({ slot }) => slot % LANES.length === index) })).filter(({ logos }) => logos.length > 0);
    return (<section className="art:w-full art:bg-background art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
      <style>{KEYFRAMES}</style>
      <div className="art:mx-auto art:grid art:w-full art:max-w-6xl art:gap-10 art:@min-[1024px]/artemis:grid-cols-[0.72fr_1.28fr] art:@min-[1024px]/artemis:items-end">
        <div className="art:max-w-lg art:pb-2">
          <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">{copy.badge}</p>
          <h2 className="art:mt-4 art:text-balance art:text-foreground art:leading-tight art:tracking-[-0.04em] art:text-4xl art:font-medium">
            {copy.headline}
          </h2>
          <p className="art:mt-5 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
            {copy.subhead}
          </p>
        </div>
        <div className="art:grid art:h-[420px] art:grid-cols-2 art:overflow-hidden art:border-border art:border-y art:[mask-image:linear-gradient(to_bottom,transparent,black_10%,black_90%,transparent)] art:@min-[640px]/artemis:h-[380px] art:@min-[640px]/artemis:[grid-template-columns:repeat(var(--logo-columns),minmax(0,1fr))]" style={{ "--logo-columns": lanes.length } as CSSProperties}>
          {lanes.map(({ lane, logos }) => (<LogoLane key={logos[0].logo.name} lane={lane} logos={logos}/>))}
        </div>
      </div>
    </section>);
}
